{
  "pr_number": "2291",
  "title": "Swap market data SDK: DataBridge -> QuantStream v3",
  "author": "Priya Raman",
  "base_branch": "main",
  "status": "open, approved by 0 reviewers, checks passing",
  "files_changed": 6,
  "additions": 214,
  "deletions": 87,
  "diff_summary": [
    {
      "file": "src/marketdata/config/vendor_config.py",
      "change": "Replaces DATABRIDGE_API_KEY / DATABRIDGE_ENDPOINT with QUANTSTREAM_API_KEY / QUANTSTREAM_ENDPOINT env vars. Removes DataBridge region-failover endpoint list (3 backup endpoints); QuantStream config only lists 1 endpoint, no documented failover region per their docs."
    },
    {
      "file": "src/marketdata/ingest/client.py",
      "change": "Swaps DataBridgeClient for QuantStreamClient SDK v3. Adds field normalization shim: QuantStream returns 'ts' (unix ms) instead of 'timestamp' (ISO8601) - shim converts on ingest."
    },
    {
      "file": "src/marketdata/ingest/reconnect.py",
      "change": "Removes DataBridgeClient's built-in auto-reconnect/backoff (was exponential backoff w/ jitter, max 10 retries). Adds new simple_retry() with fixed 3 retries, 2s delay. Inline comment: '# QuantStream SDK v3 doesn't expose a reconnect hook like DataBridge did, doing this manually for now'"
    },
    {
      "file": "tests/test_marketdata_ingest.py",
      "change": "Updates existing unit tests for new client interface (all passing). Adds test_quantstream_sandbox_integration (currently skipped, needs QUANTSTREAM_SANDBOX_CREDS)."
    },
    {
      "file": "src/marketdata/monitoring/alerts.py",
      "change": "Updates alert thresholds to reference new client's health-check method name."
    },
    {
      "file": "requirements.txt",
      "change": "Removes databridge-sdk==4.2.1, adds quantstream-sdk==3.0.2"
    }
  ],
  "review_comments": [
    {
      "author": "Priya Raman",
      "text": "Note: I couldn't find a QuantStream equivalent for DataBridge's multi-region failover, their docs only mention a single primary endpoint for our tier. Flagging in case that matters for uptime."
    }
  ]
}

